// Не отвечать на команды /start и /time
const text = msg.payload.content || "";
if (text.startsWith("/start") || text.startsWith("/time")) {
    return null; // ничего не отправляем
}

msg.payload = {
    chatId: msg.payload.chatId,
    type: "message",
    content: "Ты написал: " + text
};
return msg;
